/** Find the axis a brigade belongs to, or null if flat/not found. */
export function getBrigadeAxis(op: CorpsOperation, brigadeId: FormationId): OperationAxis | null {
    const axes = op.axes;
    if (!Array.isArray(axes) || axes.length === 0) return null;
    return axes.find(a => a.assigned_brigades.includes(brigadeId)) ?? null;
}

/** Check if a brigade participates in the operation (axis-aware). */
export function isOperationParticipant(op: CorpsOperation, brigadeId: FormationId): boolean {
    const axes = op.axes;
    if (Array.isArray(axes) && axes.length > 0) {
        return axes.some(a => a.assigned_brigades.includes(brigadeId));
    }
    return op.participating_brigades.includes(brigadeId);
}

function isPinnedActiveOperationAttacker(state: GameState, brigadeId: FormationId): boolean {
    const brigade = state.military.formations?.[brigadeId];
    const corpsId = brigade?.corps_id;
    if (!corpsId) return false;
    const cmd = state.military.corps_command?.[corpsId];
    if (!cmd) return false;
    const activeOp = findBrigadeOperation(cmd, brigadeId);
    if (!activeOp) return false;
    if (activeOp.phase !== 'execution') return false;
    if (activeOp.type !== 'sector_attack' && activeOp.type !== 'probe') return false;
    return isOperationParticipant(activeOp, brigadeId);
}

export function applySectorOffensiveDirectiveOverride(
    directive: import('../../state/game_state.js').CorpsDirective,
    activeOp: import('../../state/game_state.js').CorpsOperation,
    brigadeId?: FormationId,
): import('../../state/game_state.js').CorpsDirective {
    if (activeOp.phase !== 'execution') {
        return directive;
    }
    // Multi-axis: use the brigade's axis objectives
    const axis = brigadeId ? getBrigadeAxis(activeOp, brigadeId) : null;
    const objectives = axis ? axis.objectives : (activeOp.objectives ?? []);
    const currentIdx = axis ? axis.current_objective_index : (activeOp.current_objective_index ?? 0);
    const currentObjective = objectives[currentIdx];
    if (typeof currentObjective !== 'string' || currentObjective.length === 0) {
        return directive;
    }
    return {
        ...directive,
        offensive_targets: [currentObjective],
    };
}

export function getSectorOffensiveCurrentObjective(
    activeOp: import('../../state/game_state.js').CorpsOperation | null | undefined,
    brigadeId?: FormationId,
): Osid | null {
    if (!activeOp) return null;
    const axis = brigadeId ? getBrigadeAxis(activeOp, brigadeId) : null;
    const objectives = axis ? axis.objectives : (activeOp.objectives ?? []);
    const currentIdx = axis ? axis.current_objective_index : (activeOp.current_objective_index ?? 0);
    const currentObjective = objectives[currentIdx];
    return typeof currentObjective === 'string' && currentObjective.length > 0
        ? currentObjective as Osid
        : null;
}

export function getSectorOffensiveApproachOsids(
    state: GameState,
    activeOp: import('../../state/game_state.js').CorpsOperation,
    faction: FactionId,
    adjacency: Map<Osid, Osid[]>,
    reverseMap: OperationalToCanonicalReverseMap,
    brigadeId?: FormationId,
): Set<Osid> {
    const axis = brigadeId ? getBrigadeAxis(activeOp, brigadeId) : null;
    const objectives = axis ? axis.objectives : (activeOp.objectives ?? []);
    const currentIdx = axis ? axis.current_objective_index : (activeOp.current_objective_index ?? 0);
    const approachOsids = new Set<Osid>();
    for (const objective of objectives.slice(currentIdx)) {
        for (const neighbor of getTacticalAdjacentOsids(state, objective as Osid, adjacency)) {
            const neighborController = getPoliticalControllerOSID(state, neighbor, reverseMap);
            if (neighborController === faction || isFriendlyFaction(neighborController, faction, state)) {
                approachOsids.add(neighbor);
            }
        }
        if (approachOsids.size > 0) {
            break;
        }
    }
    return approachOsids;
}

export function getSectorOffensiveProbeThreshold(
    activeOp: import('../../state/game_state.js').CorpsOperation,
    brigadeId?: FormationId,
): PredictedOutcome {
    const axis = brigadeId ? getBrigadeAxis(activeOp, brigadeId) : null;
    const momentum = axis ? (axis.momentum ?? 0) : (activeOp.momentum ?? 0);
    // If the operation has an explicit min_attack_outcome, respect it.
    if (activeOp.min_attack_outcome) return activeOp.min_attack_outcome;
    // Default: costly_victory (ratio ≥ 1.0) — no bot should attack expecting to lose.
    // With momentum ≥ 2: stalemate (≥ 0.7) — pressing advantage, already proven you can win.
    return momentum >= 2 ? 'stalemate' : 'costly_victory';
}

function isPartOfNamedOperation(state: GameState, formation: FormationState): boolean {
    if (!formation.corps_id || !state.military.corps_command) return false;
    const cmd = state.military.corps_command[formation.corps_id];
    if (!cmd) return false;
    const op = findBrigadeOperation(cmd, formation.id);
    if (!op) return false;
    return op.phase === 'execution' && isOperationParticipant(op, formation.id);
}

// ═══════════════════════════════════════════════════════════════════════════
// Directive-based brigade execution (HoI-style: corps decides, brigade executes)
// ═══════════════════════════════════════════════════════════════════════════

/**
 * Execute corps directive for all brigades of a faction.
 * Unified for all factions — faction personality comes from the directive.
 *
 * Brigade decision flow:
 * 1. Hold OSID → DEFEND (corps says hold this position)
 * 2. Offensive target adjacent → evaluate attack using combat predictor
 * 3. Front coverage: fill gaps, spread along assigned front
 * 4. Interior: column march toward front
 * 5. Reserve: defend posture, ready to redeploy
 *
 * Deterministic: sorted brigade iteration, sorted target evaluation.
 */
function executeFactionDirectives(
    state: GameState,
    faction: FactionId,
    brigades: FormationState[],
    adjacency: Map<Osid, Osid[]>,
    reverseMap: OperationalToCanonicalReverseMap,
    terrainCache: Record<string, number>,
    graphAnalysis: FactionGraphAnalysis,
    supplyStateByOsid?: SupplyStateByOsidReport | null,
    ethnicMap?: OsidEthnicComposition,
    osidPopulationMap?: OsidPopulationMap
): OsidBotOrdersResult {
    return botOrdersPerfTime('bot_orders.executeFactionDirectives.total', () => executeFactionDirectivesImpl(
        state,
        faction,
        brigades,
        adjacency,
        reverseMap,
        terrainCache,
        graphAnalysis,
        supplyStateByOsid,
        ethnicMap,
        osidPopulationMap,
    ));
}

interface SectorAssignmentCacheEntry {
    sector: CorpsFrontSector;
    isReserve: boolean;
    frontOsids: Set<string>;
}

function collectSectorFrontOsids(sector: CorpsFrontSector): Set<string> {
    const frontOsids = new Set<string>();
    for (const subSegment of sector.sub_segments) {
        for (const osid of subSegment.friendly_osids) frontOsids.add(osid);
    }
    return frontOsids;
}

function buildSectorAssignmentByBrigade(state: GameState): Map<FormationId, SectorAssignmentCacheEntry> {
    const sectors = state.military.corps_front_sectors;
    const byBrigade = new Map<FormationId, SectorAssignmentCacheEntry>();
    if (!sectors) return byBrigade;

    for (const sectorId of Object.keys(sectors).sort(strictCompare)) {
        const sector = sectors[sectorId]!;
        const frontOsids = collectSectorFrontOsids(sector);
        for (const brigadeId of sector.assigned_brigade_ids) {
            if (!byBrigade.has(brigadeId)) {
                byBrigade.set(brigadeId, { sector, isReserve: false, frontOsids });
            }
        }
        for (const brigadeId of sector.reserve_brigade_ids) {
            if (!byBrigade.has(brigadeId)) {
                byBrigade.set(brigadeId, { sector, isReserve: true, frontOsids });
            }
        }
    }
    return byBrigade;
}

function executeFactionDirectivesImpl(
    state: GameState,
    faction: FactionId,
    brigades: FormationState[],
    adjacency: Map<Osid, Osid[]>,
    reverseMap: OperationalToCanonicalReverseMap,
    terrainCache: Record<string, number>,
    graphAnalysis: FactionGraphAnalysis,
    supplyStateByOsid?: SupplyStateByOsidReport | null,
    ethnicMap?: OsidEthnicComposition,
    osidPopulationMap?: OsidPopulationMap
): OsidBotOrdersResult {
    const result: OsidBotOrdersResult = {
        posture_orders: [],
        attack_orders: {},
        attack_scores: {},
        movement_orders: {},
        column_march_orders: {},
        eligible_attackers_by_corps: {}
    };
    const chosenTargets = new Map<Osid, number>();
    const columnAssignments = new Map<Osid, number>();
    const sectorAssignmentByBrigade = buildSectorAssignmentByBrigade(state);
    const adjacentEnemyByLoc = buildAdjacentEnemyOsidsByLoc(
        state,
        faction,
        adjacency,
        reverseMap,
        brigades.map(b => b.location_osid as Osid),
    );
    const corpsBrigadeCountsByOsid = buildCorpsBrigadeCountsByOsid(state, faction);
    const activeFormationLocationsByFaction = buildActiveFormationLocationsByFaction(state);
    const sectorDefenseByFactionAndOsid = buildSectorDefenseByFactionAndOsid(state);
    const corpsTerritoryOsidsByCorps = buildCorpsTerritoryOsidsByCorps(state);
    let officerCombatLookup: ReturnType<typeof buildOfficerCombatLookup> | undefined;
    let officerCombatLookupBuilt = false;
    const getOfficerCombatLookup = (): ReturnType<typeof buildOfficerCombatLookup> | undefined => {
        if (!state.military.named_officers || !state.military.named_officer_data) return undefined;
        if (!officerCombatLookupBuilt) {
            officerCombatLookupBuilt = true;
            officerCombatLookup = botOrdersPerfTime(
                'bot_orders.executeFactionDirectives.officerIndex',
                () => buildOfficerCombatLookup(state),
            );
        }
        return officerCombatLookup;
    };

    const corpsReserve = new Map<string, { total: number; reserved: number }>();
    for (const b of brigades) {
        if (!b.corps_id) continue;
        const existing = corpsReserve.get(b.corps_id) ?? { total: 0, reserved: 0 };
        existing.total++;
        corpsReserve.set(b.corps_id, existing);
    }

    const isAlliedWithRBiH = areRbihHrhbAllied(state);

    // ── Build sector retreat map for broadened counter-attacks ───────────
    // Scan all brigades for recent retreats; group by sector ID.
    // Determinism: iterate sorted brigades, sort retreat entries by OSID.
    const currentTurn = state.meta?.turn ?? 0;
    const sectorRecentRetreats = new Map<string, Array<{ osid: string; turn: number }>>();
    for (const b of brigades) {
        const retreatInfo = (b as { last_retreat_from?: { osid: string; turn: number } }).last_retreat_from;
        if (!retreatInfo || retreatInfo.turn < currentTurn - COUNTER_ATTACK_RETREAT_WINDOW) continue;
        const sectorId = findBrigadeSectorId(state, b);
        if (!sectorId) continue;
        let arr = sectorRecentRetreats.get(sectorId);
        if (!arr) {
            arr = [];
            sectorRecentRetreats.set(sectorId, arr);
        }
        // Avoid duplicate OSIDs within the same sector
        if (!arr.some(e => e.osid === retreatInfo.osid && e.turn === retreatInfo.turn)) {
            arr.push({ osid: retreatInfo.osid, turn: retreatInfo.turn });
        }
    }
    // Sort each sector's retreat entries by OSID for determinism
    for (const [, arr] of sectorRecentRetreats) {
        arr.sort((a, b) => strictCompare(a.osid, b.osid));
    }
    const sectorCounterAttackCount = new Map<string, number>();

    const targetAdjacentCount = new Map<Osid, number>();
    for (const b of brigades) {
        if (!b.location_osid) continue;
        const adj = adjacency.get(b.location_osid) ?? [];
        for (const n of adj) {
            targetAdjacentCount.set(n, (targetAdjacentCount.get(n) ?? 0) + 1);
        }
    }

    for (const brigade of brigades) {
        const loc = brigade.location_osid!;
        // Loaned elites use their target corps for command lookups —
        // their corps_id is still the main staff (which has no operations).
        const loanedTo = brigade.elite_loan_state?.on_loan ? brigade.elite_loan_state.loaned_to_corps : null;
        const corpsId = loanedTo ?? brigade.corps_id;
        const cmd = corpsId ? state.military.corps_command?.[corpsId] : null;
        // First try corps-local lookup (fast path). For multi-corps triggered ops
        // (op pushed onto primary corps only; secondary-axis brigade lives in a
        // foreign corps_command), corps-local lookup misses — fall back to a
        // state-wide search so secondary-axis brigades see their op during
        // planning + execution. Determinism: state-wide search iterates corps
        // ids via strictCompare. See tests/multi_corps_operation_visibility.test.ts.
        let activeOp = cmd ? findBrigadeOperation(cmd, brigade.id) : null;
        if (!activeOp) {
            const found = findBrigadeOperationAnywhere(state, brigade.id);
            if (found) activeOp = found.op;
        }
        const isActiveSectorOperationParticipant =
            (activeOp?.type === 'sector_attack' || activeOp?.type === 'probe') &&
            isOperationParticipant(activeOp, brigade.id);
            
        const directive = cmd?.directive ?? null;
        const corpsStance = cmd?.stance ?? 'balanced';
        const adjEnemy = botOrdersPerfTime(
            'bot_orders.executeFactionDirectives.adjacentEnemyScan',
            () => adjacentEnemyByLoc.get(loc) ?? getAdjacentEnemyOsids(loc, faction, adjacency, state, reverseMap),
        );

        const retreatInfo = (brigade as { last_retreat_from?: { osid: string; turn: number } }).last_retreat_from;
        const currentTurn = state.meta?.turn ?? 0;
        const counterAttackTarget: Osid | null = (retreatInfo && retreatInfo.turn === currentTurn - 1)
            ? retreatInfo.osid as Osid : null;

        const rawOsidSupplyState = getBrigadeSupplyState(brigade, supplyStateByOsid);
        const factionReserveLevel = state.meta?.supply_reserves_enabled
            ? ((state.military.general_supply_reserve as Record<string, number> | undefined)?.[brigade.faction] ?? 100)
            : 100;
        const brigadeSupplyState = state.meta?.supply_reserves_enabled
            ? getEffectiveSupplyState(rawOsidSupplyState, factionReserveLevel)
            : rawOsidSupplyState;
        const sectorAssignment = sectorAssignmentByBrigade.get(brigade.id) ?? null;
        const assignedSectorFrontOsids = sectorAssignment && !sectorAssignment.isReserve
            ? sectorAssignment.frontOsids
            : null;

        const ctx: BrigadeEvaluationContext = {
            state,
            faction,
            brigade,
            loc,
            corpsId,
            cmd: cmd ?? null,
            directive,
            corpsStance,
            activeOp,
            isActiveSectorOperationParticipant,
            adjEnemy,
            isAlliedWithRBiH,
            targetAdjacentCount,
            corpsReserve,
            chosenTargets,
            columnAssignments,
            counterAttackTarget,
            brigadeSupplyState,
            isHoldBrigade: false,
            sectorRecentRetreats,
            sectorCounterAttackCount,
            sectorAssignment,
            assignedSectorFrontOsids,
            corpsBrigadeCountsByOsid,
            activeFormationLocationsByFaction,
            sectorDefenseByFactionAndOsid,
            corpsTerritoryOsidsByCorps,
            officerCombatLookup,
            getOfficerCombatLookup,
            adjacency,
            reverseMap,
            terrainCache,
            graphAnalysis,
            supplyStateByOsid,
            ethnicMap,
            osidPopulationMap,
            result
        };

        // Skip brigades already in column transit — re-issuing orders resets progress.
        const existingTransit = state.military.brigade_movement_state?.[brigade.id];
        if (existingTransit?.stance === 'column' && existingTransit?.status === 'in_transit') {
            result.posture_orders.push({ brigade_id: brigade.id, posture: 'defend' });
            continue;
        }
        const handled = botOrdersPerfTime('bot_orders.executeFactionDirectives.evaluators', () => {
            if (botOrdersPerfTime('bot_orders.executeFactionDirectives.eval.garrisonAndDetachments', () => evaluateGarrisonAndDetachments(ctx))) return true;
            if (botOrdersPerfTime('bot_orders.executeFactionDirectives.eval.sectorMarch', () => evaluateSectorMarch(ctx))) return true;
            if (botOrdersPerfTime('bot_orders.executeFactionDirectives.eval.returnToCorps', () => evaluateReturnToCorps(ctx))) return true; // Before hold/defense — orphans march home first
            if (botOrdersPerfTime('bot_orders.executeFactionDirectives.eval.pocketEvacuation', () => evaluatePocketEvacuation(ctx))) return true; // Evacuate tiny non-enclave pockets
            if (botOrdersPerfTime('bot_orders.executeFactionDirectives.eval.homeDefense', () => evaluateHomeDefense(ctx))) return true;
            if (botOrdersPerfTime('bot_orders.executeFactionDirectives.eval.reserve', () => evaluateReserve(ctx))) return true;
            if (botOrdersPerfTime('bot_orders.executeFactionDirectives.eval.supplyGate', () => evaluateSupplyGate(ctx))) return true;
            if (botOrdersPerfTime('bot_orders.executeFactionDirectives.eval.sectorAttack', () => evaluateSectorAttack(ctx))) return true;
            if (botOrdersPerfTime('bot_orders.executeFactionDirectives.eval.uncontestedOccupation', () => evaluateUncontestedOccupation(ctx))) return true;
            if (botOrdersPerfTime('bot_orders.executeFactionDirectives.eval.hold', () => evaluateHold(ctx))) return true;
            if (botOrdersPerfTime('bot_orders.executeFactionDirectives.eval.reorganize', () => evaluateReorganize(ctx))) return true;
            if (botOrdersPerfTime('bot_orders.executeFactionDirectives.eval.defensive', () => evaluateDefensive(ctx))) return true;
            if (botOrdersPerfTime('bot_orders.executeFactionDirectives.eval.offensive', () => evaluateOffensive(ctx))) return true;
            if (botOrdersPerfTime('bot_orders.executeFactionDirectives.eval.frontCoverage', () => evaluateFrontCoverage(ctx))) return true;
            botOrdersPerfTime('bot_orders.executeFactionDirectives.eval.interiorMovement', () => evaluateInteriorMovement(ctx));
            return true;
        });
        if (handled) continue;
    }

    return result;
}

// ═══════════════════════════════════════════════════════════════════════════
// Main entry point
// ═══════════════════════════════════════════════════════════════════════════

/**
 * Generate bot brigade orders for all bot factions using directive-based execution.
 *
 * Brigades read their corps directive (generated by generate-bot-corps-orders)
 * and execute: attack directive targets, hold positions, cover front, move to front.
 *
 * Replaces the three faction-specific AIs (VRS/ARBiH/HVO) with one unified executor.
 * Faction personality is expressed through the CorpsDirective (what targets, what thresholds).
 *
 * Deterministic: faction processing in sorted order, brigades sorted by ID.
 */
export function generateAllBotOrdersOsid(
    state: GameState,
    botFactions: FactionId[],
    ctx: OsidBotContext
): BotOrderGenerationDiagnostics {
    const adjacency = (ctx.adjacency as Map<Osid, Osid[]>) ?? buildOsidAdjacency(ctx.edges);
    const terrainCache = buildTerrainCache(ctx.reverseMap);
    const sortedFactions = [...botFactions].sort(strictCompare);

    const allAttackOrders: Record<FormationId, Osid> = {};
    const allPostureOrders: Array<{ brigade_id: FormationId; posture: BrigadePosture }> = [];
    const allMovementOrders: Record<FormationId, Osid> = {};
    const allColumnMarchOrders: Record<FormationId, Osid> = {};
    const allEligibleAttackersByCorps: Record<FormationId, number> = {};

    for (const faction of sortedFactions) {
        const fmtsBrigades = state.military.formations ?? {};
        const brigades = Object.keys(fmtsBrigades).sort(strictCompare).map(k => fmtsBrigades[k]!)
            .filter((f): f is FormationState =>
                f != null &&
                f.faction === faction &&
                f.status === 'active' &&
                (f.kind === 'brigade' || f.kind === 'og' || f.kind === 'operational_group' || f.kind === 'militia' || f.kind === 'jna_phantom' || f.kind === 'hv_phantom') &&
                f.location_osid != null
            );

        if (brigades.length === 0) continue;

        const graphAnalysis = analyzeFactionGraphCached(state, faction, adjacency, ctx.reverseMap);

        const result = executeFactionDirectives(
            state, faction, brigades, adjacency, ctx.reverseMap,
            terrainCache, graphAnalysis,
            ctx.supplyStateByOsid, ctx.ethnicCompositionByOsid, ctx.osidPopulationMap
        );

        // Per-corps attack share cap: each corps gets attack slots proportional to its size.
        // This prevents large corps (1KK with 28 brigades) from monopolizing all attack slots
        // while small corps (Drina with 6 brigades) get zero.
        // Within each corps, trim lowest-scoring attacks first.
        // Winter: attack_share_mult reduces effective slots (near-total stasis Dec-Jan).
        const turn = state.meta?.turn ?? 0;
        const seasonal = getSeasonalModifiers(turn, state.meta?.scenario_start_date);
        const maxAttackShare = getEffectiveAttackShare(faction, turn, state.military.war_timeline) * seasonal.attack_share_mult;

        // Count brigades per corps
        const corpsSize = new Map<string, number>();
        for (const b of brigades) {
            const cid = b.corps_id ?? '__nocorps__';
            corpsSize.set(cid, (corpsSize.get(cid) ?? 0) + 1);
        }

        // Group attack entries by corps, with scores
        const attacksByCorps = new Map<string, Array<{ bid: FormationId; target: Osid; score: number }>>();
        for (const [bid, target] of Object.entries(result.attack_orders)) {
            if (target == null) continue;
            const brig = state.military.formations?.[bid as FormationId];
            const cid = brig?.corps_id ?? '__nocorps__';
            if (!attacksByCorps.has(cid)) attacksByCorps.set(cid, []);
            attacksByCorps.get(cid)!.push({
                bid: bid as FormationId,
                target: target as Osid,
                score: result.attack_scores[bid as FormationId] ?? 0
            });
        }

        // Per-corps trimming: each corps gets max(1, floor(size * attackShare)) slots
        for (const [cid, attacks] of [...attacksByCorps.entries()].sort((a, b) => strictCompare(a[0], b[0]))) {
            const size = corpsSize.get(cid) ?? 1;
            const maxCorpsAttacks = Math.max(1, Math.floor(size * maxAttackShare));
            if (attacks.length <= maxCorpsAttacks) continue;

            // Sort by score DESC, deterministic tiebreak
            attacks.sort((a, b) => {
                if (b.score !== a.score) return b.score - a.score;
                return strictCompare(a.bid, b.bid);
            });
            const pinned = attacks.filter((entry) => isPinnedActiveOperationAttacker(state, entry.bid));
            const trimmable = attacks.filter((entry) =>
                !isPinnedActiveOperationAttacker(state, entry.bid)
                && entry.score !== UNCONTESTED_OCCUPATION_SCORE
            );
            const keepTrimmable = Math.max(0, maxCorpsAttacks - pinned.length);
            const trimmed = trimmable.slice(keepTrimmable);
            for (const entry of trimmed) {
                delete result.attack_orders[entry.bid];
                delete result.attack_scores[entry.bid];
                result.posture_orders.push({ brigade_id: entry.bid, posture: 'hold' });
            }
        }

        // C.2: ARBiH warlord friction — before w78, one attacking brigade per corps
        // is forced to defend each turn (deterministic: turn % attackingBrigadeCount).
        // Simulates lack of unified command / warlord autonomy in early ARBiH.
        // D.4: Read warlord friction end week from war_timeline if available
        const warlordFrictionEndWeek = state.military.war_timeline?.officer_config?.RBiH?.warlord_friction_end_week ?? 78;
        if (faction === 'RBiH' && turn < warlordFrictionEndWeek) {
            for (const [cid, attacks] of [...attacksByCorps.entries()].sort((a, b) => strictCompare(a[0], b[0]))) {
                const trimmable = attacks.filter((entry) =>
                    !isPinnedActiveOperationAttacker(state, entry.bid)
                    && entry.score !== UNCONTESTED_OCCUPATION_SCORE
                );
                if (trimmable.length <= 1) continue; // Need at least 2 non-operation attackers for friction
                // Sort by bid for deterministic selection
                const sorted = [...trimmable].sort((a, b) => strictCompare(a.bid, b.bid));
                const frictionIndex = turn % sorted.length;
                const frictionTarget = sorted[frictionIndex]!;
                // Remove from attack orders, force hold (warlord friction: unit refuses orders)
                delete result.attack_orders[frictionTarget.bid];
                delete result.attack_scores[frictionTarget.bid];
                result.posture_orders.push({ brigade_id: frictionTarget.bid, posture: 'hold' });
            }
        }

        // Accumulate results
        const finalEligibleAttackersByCorps: Record<FormationId, number> = {};
        for (const bid of Object.keys(result.attack_orders).sort(strictCompare)) {
            const brig = state.military.formations?.[bid as FormationId];
            const corpsId = brig?.corps_id;
            if (!corpsId) continue;
            finalEligibleAttackersByCorps[corpsId] = (finalEligibleAttackersByCorps[corpsId] ?? 0) + 1;
        }
        allPostureOrders.push(...result.posture_orders);
        for (const [bid, target] of Object.entries(result.attack_orders)) {
            if (target != null) allAttackOrders[bid as FormationId] = target;
        }
        for (const [bid, dest] of Object.entries(result.movement_orders)) {
            if (dest != null) allMovementOrders[bid as FormationId] = dest;
        }
        for (const [bid, dest] of Object.entries(result.column_march_orders)) {
            if (dest != null) allColumnMarchOrders[bid as FormationId] = dest;
        }
        for (const corpsId of Object.keys(finalEligibleAttackersByCorps).sort(strictCompare)) {
            allEligibleAttackersByCorps[corpsId] =
                (allEligibleAttackersByCorps[corpsId] ?? 0) + finalEligibleAttackersByCorps[corpsId]!;
        }
    }

    // ── Graz Accords enforcement: remove RS↔HRHB attacks violating ceasefire ──
    // Exception: brigades in a corps with an active operation AND the east Herzegovina
    // pair truce hasn't activated yet (Op Jackal still running) are exempt.
    if (isGrazAccordsActive(state)) {
        const pc = state.political.political_controllers ?? {};
        const formations = state.military.formations ?? {};
        const corpsCmd = state.military.corps_command ?? {};
        for (const bid of Object.keys(allAttackOrders)) {
            const target = allAttackOrders[bid as FormationId];
            if (!target) continue;
            const f = formations[bid];
            if (!f) continue;
            const corpsId = f.corps_id ?? '';
            const faction = f.faction;
            const targetController = pc[target] ?? '';
            // Skip Graz block for brigades attacking Op Jackal objectives only
            const grazCmd = corpsCmd[corpsId];
            if (grazCmd && grazCmd.active_operations.length > 0
                && isEastHerzegovinaPair(corpsId)
                && state.political.graz_east_herzegovina_active_turn == null) {
                // Check if target is an objective of any active operation
                let isOpObjective = false;
                for (const op of grazCmd.active_operations) {
                    const opObjectives = new Set(
                        op.axes?.flatMap(a => a.objectives ?? []) ?? op.objectives ?? []
                    );
                    if (opObjectives.has(target)) { isOpObjective = true; break; }
                }
                if (isOpObjective) continue; // Target is an op objective — allow
                // Non-objective RS targets still blocked by Graz
            }
            if (shouldGrazBlockAttack(state, corpsId, faction, target, targetController)) {
                delete allAttackOrders[bid as FormationId];
            }
        }
    }

    // Write to state
    if (!state.military.brigade_posture_orders) state.military.brigade_posture_orders = [];
    state.military.brigade_posture_orders.push(...allPostureOrders);

    if (Object.keys(allAttackOrders).length > 0) {
        state.military.brigade_attack_orders = allAttackOrders;
    }

    // Movement orders: merge regular moves + column march destinations
    const mergedMovement: Record<FormationId, BrigadeMovementOrder> = {};
    for (const [bid, dest] of Object.entries(allMovementOrders)) {
        mergedMovement[bid as FormationId] = { destination_sids: [dest] };
    }
    for (const [bid, dest] of Object.entries(allColumnMarchOrders)) {
        // Column march: write to movement orders with stance:'column' so the
        // column movement processor (processOsidColumnMovement) picks them up.
        mergedMovement[bid as FormationId] = { destination_sids: [dest], stance: 'column' };
    }
    if (Object.keys(mergedMovement).length > 0) {
        state.military.brigade_movement_orders = mergedMovement;
    }

    return {
        eligible_attackers_by_corps: allEligibleAttackersByCorps
    };
}
